from collections import defaultdict


def word_count(text: str) -> dict[str, int]:
    cleaned = "".join(ch.lower() if ch.isalnum() or ch.isspace() else " " for ch in text)
    tally = defaultdict(int)
    for word in cleaned.split():
        tally[word] += 1
    return dict(tally)


