def is_palindrome(s: str) -> bool:
    chars = "".join(filter(str.isalnum, s)).lower()

    def check(lo: int, hi: int) -> bool:
        if lo >= hi:
            return True
        return chars[lo] == chars[hi] and check(lo + 1, hi - 1)

    return check(0, len(chars) - 1)


